-- Medical Progress Archive (phase 1): a worldwide, year-by-year record of developments that matter to doctors.
-- Extends recent_developments. Archive rows are curated and verified against Crossref (DOI, title, date); all text is in our own words.
-- The weekly scan keeps filling the "Latest" tab (origin = 'weekly_scan'); the Archive tab shows origin = 'archive'.
alter table public.recent_developments drop constraint if exists recent_developments_category_check;
alter table public.recent_developments add constraint recent_developments_category_check check (category in
  ('new_drug_approval','safety_alert','guideline_update','key_trial','regulatory_decision','public_health',
   'vaccine','procedure_gene_cell_therapy','device_diagnostic','risk_score_criteria','definition_classification'));

alter table public.recent_developments drop constraint if exists recent_developments_summary_source_check;
alter table public.recent_developments add constraint recent_developments_summary_source_check
  check (summary_source is null or summary_source in ('pubmed_abstract','curated'));

alter table public.recent_developments
  add column if not exists origin text not null default 'weekly_scan' check (origin in ('weekly_scan','archive')),
  add column if not exists year integer generated always as (extract(year from published_at)::integer) stored,
  add column if not exists significance smallint not null default 2 check (significance in (1,2,3)),
  add column if not exists why_it_matters text check (why_it_matters is null or char_length(why_it_matters) <= 400),
  add column if not exists region text not null default 'global' check (region in ('global','gcc','ksa')),
  add column if not exists sfda_status text,
  add column if not exists source_label text,
  add column if not exists source_checked_at timestamptz,
  add column if not exists source_checked_by text;

create index if not exists recent_developments_archive_idx on public.recent_developments (origin, status, year desc, significance);

create or replace view public.recent_development_year_counts with (security_invoker = true) as
  select year, category, significance, region, count(*)::int as n
  from public.recent_developments
  where origin = 'archive' and status = 'published'
  group by year, category, significance, region;
grant select on public.recent_development_year_counts to authenticated;

insert into public.dev_sources (id, name, tier, kind, url)
  values ('archive-curated', 'Curated archive (verified against Crossref)', 'C', 'api', 'https://api.crossref.org/works')
  on conflict (id) do nothing;

insert into public.recent_developments
  (source_id, origin, status, summary_source, source_checked_at, source_checked_by,
   source_url, doi, category, title, summary, published_at, specialities, significance, why_it_matters, source_label, saudi_relevant)
select 'archive-curated','archive','published','curated', now(), 'crossref-doi', v.source_url, v.doi, v.category, v.title, v.summary, v.published_at::date, v.specialities, v.significance::smallint, v.why_it_matters, v.source_label, v.saudi_relevant
from (values
  ('https://doi.org/10.1001/jama.2016.0287', '10.1001/jama.2016.0287', 'definition_classification', 'Sepsis-3: new definitions of sepsis and septic shock', 'Sepsis is redefined as life-threatening organ dysfunction caused by a dysregulated response to infection, identified by a rise of 2 or more SOFA points; qSOFA is proposed as a bedside prompt.', '2016-02-23', array['Emergency Medicine','Internal Medicine']::text[], 1, 'Replaced SIRS-based definitions used in emergency departments and wards worldwide.', 'JAMA', false),
  ('https://doi.org/10.1056/NEJMoa1603827', '10.1056/NEJMoa1603827', 'key_trial', 'LEADER: liraglutide lowers cardiovascular events in type 2 diabetes', 'In 9,340 adults with type 2 diabetes at high cardiovascular risk, liraglutide reduced major cardiovascular events and cardiovascular death compared with placebo.', '2016-07-28', array['Endocrinology','Cardiology']::text[], 1, 'First GLP-1 receptor agonist shown to reduce cardiovascular death; began the shift to outcome-driven diabetes drug choice.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1093/eurheartj/ehw272', '10.1093/eurheartj/ehw272', 'guideline_update', '2016 ESC/EAS guidelines for the management of dyslipidaemias', 'European guidance on lipid testing, risk-based LDL cholesterol targets and treatment.', '2016-08-28', array['Cardiology','Endocrinology']::text[], 2, 'Reference for lipid targets in Europe and the Middle East until the 2019 update.', 'European Heart Journal', true),
  ('https://doi.org/10.1056/NEJMoa1513257', '10.1056/NEJMoa1513257', 'key_trial', 'Venetoclax in relapsed chronic lymphocytic leukaemia', 'Targeting BCL2 with venetoclax produced responses in about 79% of 116 patients with relapsed or refractory CLL.', '2016-01-28', array['Internal Medicine']::text[], 2, 'Led to the first approval of a BCL2 inhibitor (FDA, April 2016).', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1615664', '10.1056/NEJMoa1615664', 'key_trial', 'FOURIER: evolocumab added to a statin lowers cardiovascular events', 'In 27,564 patients with atherosclerotic disease on statins, adding evolocumab lowered LDL cholesterol and reduced major cardiovascular events (about 15% relative reduction in the primary endpoint).', '2017-05-04', array['Cardiology']::text[], 1, 'Showed that lowering LDL cholesterol far below earlier targets is beneficial; supports PCSK9-inhibitor use in very-high-risk patients.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1707914', '10.1056/NEJMoa1707914', 'key_trial', 'CANTOS: targeting inflammation with canakinumab lowers cardiovascular events', 'In 10,061 patients after myocardial infarction with raised hs-CRP, canakinumab 150 mg reduced recurrent cardiovascular events without lowering cholesterol.', '2017-09-21', array['Cardiology']::text[], 1, 'First proof that lowering inflammation, independent of lipids, reduces atherosclerotic events; not adopted widely because of infection risk and cost.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1709118', '10.1056/NEJMoa1709118', 'key_trial', 'COMPASS: low-dose rivaroxaban plus aspirin in stable vascular disease', 'In 27,395 patients with stable coronary or peripheral artery disease, rivaroxaban 2.5 mg twice daily plus aspirin reduced cardiovascular events versus aspirin alone, with more major bleeding.', '2017-10-05', array['Cardiology']::text[], 2, 'Opened the option of dual-pathway inhibition for selected high-risk outpatients.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1611925', '10.1056/NEJMoa1611925', 'key_trial', 'CANVAS: canagliflozin and cardiovascular events in type 2 diabetes', 'An integrated analysis of two trials in 10,142 participants found fewer major cardiovascular events with canagliflozin and an increased risk of amputation.', '2017-08-17', array['Endocrinology','Cardiology']::text[], 2, 'Part of the evidence that moved SGLT2 inhibitors from glucose-lowering drugs to cardiovascular and kidney protection.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1161/HYP.0000000000000065', '10.1161/HYP.0000000000000065', 'guideline_update', '2017 ACC/AHA high blood pressure guideline', 'Defines hypertension as 130/80 mmHg or higher and recommends earlier treatment with out-of-office confirmation.', '2018-06-01', array['Cardiology','Internal Medicine']::text[], 1, 'Changed the US threshold and prompted worldwide debate; European guidelines kept 140/90 for diagnosis.', 'Hypertension', false),
  ('https://doi.org/10.1056/NEJMoa1707447', '10.1056/NEJMoa1707447', 'key_trial', 'ZUMA-1: axicabtagene ciloleucel (CAR-T) in refractory large B-cell lymphoma', 'In 101 patients with refractory large B-cell lymphoma, one CAR-T infusion produced an objective response in 82% and a complete response in 54%.', '2017-12-28', array['Internal Medicine']::text[], 1, 'Basis of the first CAR-T approvals for lymphoma (FDA, October 2017); needs specialist centres to manage cytokine release and neurotoxicity.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1016/S0140-6736(17)31868-8', '10.1016/S0140-6736(17)31868-8', 'key_trial', 'Voretigene neparvovec (Luxturna): gene therapy for RPE65 retinal dystrophy', 'A phase 3 trial of a one-time subretinal gene therapy showed improved functional vision in patients with biallelic RPE65 mutations.', '2017-08-01', array['Internal Medicine']::text[], 1, 'First gene therapy approved for an inherited disease in the US (December 2017).', 'The Lancet', false),
  ('https://doi.org/10.1056/NEJMoa1606468', '10.1056/NEJMoa1606468', 'key_trial', 'ORATORIO: ocrelizumab in primary progressive multiple sclerosis', 'Ocrelizumab slowed confirmed disability progression versus placebo in primary progressive multiple sclerosis.', '2017-01-19', array['Neurology']::text[], 2, 'First therapy to show benefit in primary progressive MS (FDA, March 2017).', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1702752', '10.1056/NEJMoa1702752', 'key_trial', 'Nusinersen in infantile-onset spinal muscular atrophy', 'A motor-milestone response occurred in 51% of treated infants versus 0% with sham procedure.', '2017-11-02', array['Neurology']::text[], 1, 'First treatment for spinal muscular atrophy (FDA, December 2016); changed the outlook of a fatal infant disease.', 'New England Journal of Medicine', false),
  ('https://doi.org/10.1056/NEJMoa1706198', '10.1056/NEJMoa1706198', 'key_trial', 'Single-dose gene-replacement therapy for spinal muscular atrophy', 'All 15 infants who received onasemnogene abeparvovec were alive and event-free at 20 months, compared with about 8% in historical controls.', '2017-11-02', array['Neurology']::text[], 1, 'Basis for Zolgensma, approved in 2019 as a one-time gene therapy.', 'New England Journal of Medicine', false),
